def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    last_my = history[-1][0]
    last_opp = history[-1][1]

    if n <= 4 and opp_d <= 1:
        return 'C'

    if n == 2 and opp_d == 2:
        return 'D'

    all_c_samples = 0
    all_c_coop = 0
    all_d_samples = 0
    all_d_coop = 0
    rec_c_samples = 0
    rec_c_coop = 0
    rec_d_samples = 0
    rec_d_coop = 0

    rec_start = n - 11
    if rec_start < 0:
        rec_start = 0

    for i in range(n - 1):
        prev_my = history[i][0]
        next_opp = history[i + 1][1]
        recent = i >= rec_start
        if prev_my == 'C':
            all_c_samples += 1
            if next_opp == 'C':
                all_c_coop += 1
            if recent:
                rec_c_samples += 1
                if next_opp == 'C':
                    rec_c_coop += 1
        else:
            all_d_samples += 1
            if next_opp == 'C':
                all_d_coop += 1
            if recent:
                rec_d_samples += 1
                if next_opp == 'C':
                    rec_d_coop += 1

    if rec_c_samples > 0:
        c_used_samples = float(rec_c_samples)
        c_used_coop = float(rec_c_coop)
    else:
        c_used_samples = float(all_c_samples)
        c_used_coop = float(all_c_coop)

    if rec_d_samples > 0:
        d_used_samples = float(rec_d_samples)
        d_used_coop = float(rec_d_coop)
    else:
        d_used_samples = float(all_d_samples)
        d_used_coop = float(all_d_coop)

    base = float(opp_c) / float(n)

    if base >= 0.95:
        prior0 = 0.92
    elif base >= 0.85:
        prior0 = 0.86
    elif base >= 0.70:
        prior0 = 0.78
    elif base >= 0.50:
        prior0 = 0.68
    elif base >= 0.30:
        prior0 = 0.52
    else:
        prior0 = 0.40

    if last_opp == 'C':
        prior1 = 0.28
        if base >= 0.95:
            prior1 = 0.30
    else:
        prior1 = 0.20
        if base >= 0.90:
            prior1 = 0.23

    if opp_d <= 1 and n <= 10:
        prior1 = 0.18

    prior_w = 7.0
    p0 = (c_used_coop + prior_w * prior0) / (c_used_samples + prior_w)
    p1 = (d_used_coop + prior_w * prior1) / (d_used_samples + prior_w)

    h = 100 - n
    v0 = 0.0
    v1 = 0.0

    for _ in range(h - 1):
        n0 = v0
        n1 = v1
        v0 = max(3.0 * p0 + n0, 1.0 + 4.0 * p0 + n1)
        v1 = max(3.0 * p1 + n0, 1.0 + 4.0 * p1 + n1)

    if last_my == 'C':
        val_c = 3.0 * p0 + v0
        val_d = 1.0 + 4.0 * p0 + v1
    else:
        val_c = 3.0 * p1 + v0
        val_d = 1.0 + 4.0 * p1 + v1

    if val_d > val_c:
        return 'D'
    return 'C'
